CREATE OR REPLACE FUNCTION public.invitation_eligible(_uid uuid,_availability uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.guest_ready(_uid) AND EXISTS(SELECT 1 FROM public.availability a JOIN public.host_profiles h ON h.person_id=a.host_id JOIN public.persons hp ON hp.id=h.person_id JOIN public.guest_profiles g ON g.person_id=_uid LEFT JOIN public.cities c ON c.name=h.city WHERE a.id=_availability AND a.status='open' AND NOT EXISTS(SELECT 1 FROM public.hostings bh WHERE bh.guest_id=_uid AND bh.shabbat_date=a.shabbat_date AND bh.status IN ('confirmed','under_review')) AND a.seats_left>=g.party_adults+g.minor_children_count AND (NOT a.with_lodging OR a.beds-COALESCE((SELECT sum(party_size) FROM public.hostings WHERE availability_id=a.id AND status IN ('confirmed','under_review')),0)>=g.party_adults+g.minor_children_count) AND h.approval='approved' AND h.status='active' AND hp.restriction_status='none' AND public.invitation_before_cutoff(a.shabbat_date) AND a.unit=g.default_unit AND a.with_lodging=g.default_with_lodging AND (NOT a.with_lodging OR (h.rule_separate_room AND h.rule_lockable_door)) AND h.languages && g.languages AND (g.area_all_israel OR c.region=ANY(g.regions)) AND (h.guest_gender_pref='everyone' OR (h.guest_gender_pref='women_only' AND g.gender='female' AND g.party_adults=1 AND g.minor_children_count=0) OR (h.guest_gender_pref='men_only' AND g.gender='male' AND g.party_adults=1 AND g.minor_children_count=0) OR (h.guest_gender_pref='families_couples' AND g.party_adults+g.minor_children_count>1))) $$;
-- Maintain eligibility after a concurrent seat mutation, not only before the lock.
CREATE OR REPLACE FUNCTION public.guard_pending_response() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.status='pending' AND TG_OP='INSERT' THEN
IF EXISTS(SELECT 1 FROM public.hostings WHERE guest_id=NEW.guest_id AND shabbat_date=(SELECT shabbat_date FROM public.availability WHERE id=NEW.availability_id) AND status IN ('confirmed','under_review')) OR NOT public.invitation_eligible(NEW.guest_id,NEW.availability_id) THEN RAISE EXCEPTION 'invitation_unavailable'; END IF;
END IF;
IF NEW.status='accepted' AND OLD.status='pending' THEN
IF NOT EXISTS(SELECT 1 FROM public.guest_profiles g JOIN public.requests q ON q.id=NEW.request_id JOIN public.availability a ON a.id=NEW.availability_id JOIN public.host_profiles h ON h.person_id=a.host_id WHERE g.person_id=NEW.guest_id AND g.party_adults=q.adults AND g.minor_children_count=cardinality(q.children_ages) AND (NOT a.with_lodging OR (h.rule_separate_room AND h.rule_lockable_door))) THEN RAISE EXCEPTION 'response_unavailable'; END IF;
END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_pending_response() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER responses_guard_booking BEFORE INSERT OR UPDATE ON public.responses FOR EACH ROW EXECUTE FUNCTION public.guard_pending_response();
COMMENT ON FUNCTION public.confirm_host_response(uuid,public.contact_method,boolean) IS 'Intentional authenticated SECURITY DEFINER boundary: checks host ownership, approved host and verified guest, locks guest/availability/response, enforces unique guest-date; anonymous execution revoked.';
COMMENT ON FUNCTION public.decline_host_response(uuid,text,text) IS 'Intentional authenticated SECURITY DEFINER boundary: requires pending response owned by caller host. Reasons are excluded from guest-readable column grants.';
COMMENT ON FUNCTION public.hosting_details(uuid) IS 'Intentional authenticated SECURITY DEFINER private projection: participant ownership checked and phone/address returned only for confirmed status.';
COMMENT ON FUNCTION public.my_hosting_summaries() IS 'Intentional authenticated SECURITY DEFINER safe projection: returns only caller-participant hostings and never phone, address or staff-only fields.';